<?php use Clinica\Services\{PatientProfileValidator,SessionService}; $values = $values ?? $profile; ?>
<div class="patient-page-heading"><div><span class="eyebrow text-secondary">CU20</span><h1>Mi perfil</h1><p class="text-secondary mb-0">Los datos de identificación e historial básico son de solo consulta.</p></div></div>
<?php if($message): ?><div class="alert alert-success"><?= $escape($message) ?></div><?php endif; ?><?php if($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $error): ?><li><?= $escape($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><?php if(!$writesEnabled = \Clinica\Support\PatientProfileFactory::writesEnabled()): ?><div class="alert alert-info">La edición está temporalmente deshabilitada; esta pantalla no cambia PostgreSQL.</div><?php endif; ?>
<section class="patient-card mb-4"><h2 class="h5">Datos personales</h2><dl class="row mb-0"><dt class="col-sm-4">Código</dt><dd class="col-sm-8"><?= $escape($values['codigo_paciente']) ?></dd><dt class="col-sm-4">Documento</dt><dd class="col-sm-8"><?= $escape($values['documento_identidad']) ?></dd><dt class="col-sm-4">Nombre</dt><dd class="col-sm-8"><?= $escape($values['nombres'].' '.$values['apellidos']) ?></dd><dt class="col-sm-4">Nacimiento</dt><dd class="col-sm-8"><?= $escape($values['fecha_nacimiento']) ?></dd><dt class="col-sm-4">Sexo</dt><dd class="col-sm-8"><?= $escape($values['sexo']) ?></dd></dl></section>
<form method="post" action="/mi-perfil" class="patient-card patient-form"><input type="hidden" name="csrf" value="<?= $escape(SessionService::csrf()) ?>"><fieldset><legend>Contacto y salud</legend><div class="row g-4"><?php foreach(PatientProfileValidator::FIELDS as $field=>[$label,$max,$required]): $error=$errors[$field] ?? null; ?><div class="<?= in_array($field,['direccion','alergias','antecedentes_relevantes'],true) ? 'col-12' : 'col-md-6' ?>"><label class="form-label" for="<?= $field ?>"><?= $escape($label) ?></label><?php if(in_array($field,['direccion','alergias','antecedentes_relevantes'],true)): ?><textarea class="form-control" id="<?= $field ?>" name="<?= $field ?>" rows="3" <?= !$writesEnabled?'disabled':'' ?>><?= $escape($values[$field]) ?></textarea><?php else: ?><input class="form-control" id="<?= $field ?>" name="<?= $field ?>" value="<?= $escape($values[$field]) ?>" <?= $max?'maxlength="'.$max.'"':'' ?> <?= !$writesEnabled?'disabled':'' ?>><?php endif; ?><?php if($error): ?><div class="invalid-feedback d-block"><?= $escape($error) ?></div><?php endif; ?></div><?php endforeach; ?></div></fieldset><button class="btn btn-clinic mt-4" type="submit" <?= !$writesEnabled?'disabled':'' ?>>Guardar cambios</button></form>
